def build_agent(sandbox):
    # Lower sieve for small particles (gaps ≥0.16m)
    # 7 beams, each 0.08m wide, 0.1m tall, spaced 0.16m apart
    # Starting x at 5.29m, y=1.87m
    x_lower_start = 5.29
    y_lower = 1.87
    for i in range(7):
        beam = sandbox.add_static_beam(x_lower_start + i * (0.08 + 0.16), y_lower, 0.08, 0.1, angle=0, density=150.0)
        sandbox.set_material_properties(beam, restitution=0.0)

    # Upper sieve for medium particles (gaps ≥0.24m)
    # 6 beams, each 0.08m wide, 0.1m tall, spaced 0.24m apart
    # Starting x at 5.21m, y=2.40m
    x_upper_start = 5.21
    y_upper = 2.40
    for i in range(6):
        beam = sandbox.add_static_beam(x_upper_start + i * (0.08 + 0.24), y_upper, 0.08, 0.1, angle=0, density=150.0)
        sandbox.set_material_properties(beam, restitution=0.0)

    return None  # No chassis needed, just the beams

def agent_action(sandbox, agent_body, step_count):
    # Apply downward forces to small and medium particles that are above their target zones
    if step_count % 32 != 0:
        return
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -30.0))
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -25.5))
